/**
 * The `skipGeneratedFiles` counterpart to `skip-test-files.test.ts`.
 *
 * Rules about maintainability — duplication, complexity, parameter counts —
 * are advice to whoever edits the file next. Generated code has no such reader:
 * the next run of the generator rewrites it, and its header usually says so.
 * Measured on the pinned 8-repository corpus, generated files were 32% of
 * `cognitive-complexity` findings and 27% of `max-parameters` findings, almost
 * all of it twilio-node's OpenAPI-generated `src/rest/**`.
 *
 * The same opt-in reasoning as `skipTestFiles` applies — one `createRule` is
 * shared by every plugin here — plus one line that does not: a SECURITY rule
 * must never set this. Generated code ships and runs, so an injection in it is
 * a live vulnerability whoever typed it.
 */
import { describe, it, expect } from 'vitest';
import { Linter } from 'eslint';
import { createRule } from './rule-creator';

const BANNER = `/*
 * This code was generated by OpenAPI Generator.
 * Do not edit the class manually.
 */`;

describe('createRule skipGeneratedFiles gate', () => {
  const mk = (skipGeneratedFiles: boolean) =>
    createRule<[], 'hit'>({
      name: 'probe',
      meta: {
        type: 'problem',
        docs: { description: 'probe' },
        schema: [],
        messages: { hit: 'hit' },
      },
      skipGeneratedFiles,
      defaultOptions: [],
      create: (context) => ({
        VariableDeclarator: (node) =>
          context.report({ node, messageId: 'hit' }),
      }),
    });

  const run = (probe: unknown, code: string) =>
    new Linter({ configType: 'flat' })
      .verify(
        code,
        [
          {
            // NOT `**/*` — see the note in skip-test-files.test.ts. A universal
            // pattern yields a `ruleId: null` message a naive probe miscounts.
            files: ['**/*.{js,mjs,cjs,jsx,ts,tsx,mts,cts}'],
            plugins: { p: { rules: { probe } } },
            rules: { 'p/probe': 'error' },
          },
        ] as never,
        'src/rest/bulk.ts',
      )
      .filter((m) => m.ruleId).length;

  it('suppresses in a file that declares itself generated', () => {
    expect(run(mk(true), `${BANNER}\nconst x = 1;`)).toBe(0);
    expect(run(mk(true), '/** @generated */\nconst x = 1;')).toBe(0);
  });

  it('still reports in hand-written files when opted in', () => {
    // Without this, "suppresses in generated files" also passes on a rule that
    // suppresses everywhere.
    expect(run(mk(true), 'const x = 1;')).toBe(1);
  });

  it('CONTROL: reports in generated files when NOT opted in', () => {
    // The mutation check. If this returns 0 the flag has become a no-op and
    // both assertions above would pass on a rule that never had the gate.
    expect(run(mk(false), `${BANNER}\nconst x = 1;`)).toBe(1);
  });

  it('does not accept a banner below the first statement', () => {
    // A banner is a header. Otherwise any comment anywhere in a file buys a
    // whole-file suppression for free.
    expect(
      run(mk(true), 'const x = 1;\n// this code was generated by hand'),
    ).toBe(1);
  });
});
